import{_ as s,a0 as a,w as r,s as d,ao as l,I as p,x as t,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何在Linux中發現IP地址衝突 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中發現IP地址衝突 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中發現IP地址衝突 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中發現IP地址衝突 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How To Find IP Conflicts In Linux","title":"如何在Linux中發現IP地址衝突","tag":"201404","desc":""},"relativePath":"201404/How To Find IP Conflicts In Linux.md","filePath":"[post].md"}'),u={name:"201404/How To Find IP Conflicts In Linux.md"};function I(P,n,x,T,f,m){const e=a("Link");return r(),d("div",null,[n[11]||(n[11]=l(`<h1 id="如何在linux中發現ip地址衝突" tabindex="-1">如何在Linux中發現IP地址衝突 <a class="header-anchor" href="#如何在linux中發現ip地址衝突" aria-label="Permalink to “如何在Linux中發現IP地址衝突”">​</a></h1><p>你們都知道什麼是IP地址，是吧？它們被分配給網絡上的設備來代表它們。它們通過DHCP服務器分配並且會經常改變。現在有兩種IP地址。動態的一種會經常改變（幾天一次），而靜態的就如它的名字那樣是靜態的，意味着它們不會改變。</p><p>有時這會引發一些衝突。當一個動態IP被分配了並且有另外一台網絡設備已經擁有了相同的IP。或者在相同網絡子網上有多台分配IP的DHCP服務器。如果你有連通問題並且假設它是由於IP衝突造成的，那麼你可以使用一個工具稱作arp-scan來掃描它們。</p><p>這個工具會在本地網絡發送ARP（Address Resolution Protocol）(地址解析協議)包來收集地址。如果有多個MAC地址聲稱擁有相同的IP地址，那麼這裏就存在衝突。</p><p>要在Ubuntu或者Debian上安裝arp-scan則輸入：</p><pre><code>$ sudo apt-get install arp-scan
</code></pre><p>對於Fedora，CentOS或者RedHat：</p><pre><code>$ sudo yum install arp-scan
</code></pre><p>要檢測IP衝突，運行下面的命令:</p><pre><code>$ sudo arp-scan –I eth0 -l
</code></pre><p>輸出示例：</p><pre><code>192.168.1.10   00:1b:a9:63:a2:4c       BROTHER INDUSTRIES, LTD.
192.168.1.30   00:1e:8f:58:ec:49       CANON INC.
192.168.1.33   00:25:4b:1b:10:20       Apple, Inc
192.168.1.37   10:9a:dd:55:d7:95       Apple Inc
192.168.1.38   20:c9:d0:27:8d:56       (Unknown)
192.168.1.39   d4:85:64:4d:35:be       Hewlett Packard
192.168.1.39   00:0b:46:e4:8e:6d       Cisco (DUP: 2)
192.168.1.40   90:2b:34:18:59:c0       (Unknown)
</code></pre><p>在本例中，<strong>192.168.1.39</strong>這個IP衝突了，因為它出現了兩次。</p><hr>`,14)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),o(e,{href:"http://www.unixmen.com/find-ip-conflicts-linux/"},{default:i(()=>[...n[0]||(n[0]=[t("http://www.unixmen.com/find-ip-conflicts-linux/",-1)])]),_:1})]),p("p",null,[n[4]||(n[4]=t("譯者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:i(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[n[8]||(n[8]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const w=s(u,[["render",I]]);export{c as __pageData,w as default};
